 Widget balancesView(){if(!widget.admin){final b=data['balance']??{'amount':0};final amount=b['amount'] as num;return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[text('Your home. Your balance.',size:28,weight:FontWeight.w700),const SizedBox(height:12),text('Private to your apartment.',color:muted),const SizedBox(height:24),card(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[text('APARTMENT ${me?['apartment']}',size:11,color:muted,weight:FontWeight.w700),const SizedBox(height:22),text(kzt(amount.abs()),size:38,weight:FontWeight.w700,color:amount<0?const Color(0xFFDC6A70):blue),const SizedBox(height:8),text(amount<0?'Outstanding balance':amount>0?'Prepaid · thank you':'All paid. You are up to date.',weight:FontWeight.w600),const SizedBox(height:22),text('The OSI accountant updates this balance from the building records. No other resident can see it.',color:muted)]))]);}
 final rows=data['balances'] as List? ?? [];return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[text('Clear books. Clearer decisions.',size:28,weight:FontWeight.w700),const SizedBox(height:8),text('Apartment balances · visible only to building management',color:muted),const SizedBox(height:22),button('Upload balances CSV',()=>action(()async{final files=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['csv'],withData:true);if(files==null)return;final f=files.files.single;if(f.bytes==null)throw Exception('Cannot read CSV');final count=await api.importBalances(f.bytes!,f.name);await refresh();if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$count apartment balances imported')));}),icon:Icons.upload_file),const SizedBox(height:14),text('CSV: apartment,balance · whole KZT · negative = debt · positive = prepaid\nAll rows are validated before anything is saved. Example: demo/balances.csv',size:12,color:muted),const SizedBox(height:24),...rows.map((b){final amount=b['amount'] as num;return Padding(padding:const EdgeInsets.only(bottom:8),child:card(Row(children:[const Icon(Icons.apartment,color:muted),const SizedBox(width:14),Expanded(child:text('Apartment ${b['apartment']}',weight:FontWeight.w600)),text(amount<0?'Debt':amount>0?'Prepaid':'Paid',size:12,color:amount<0?const Color(0xFFD96873):const Color(0xFF1A9474)),const SizedBox(width:20),SizedBox(width:120,child:Align(alignment:Alignment.centerRight,child:text(kzt(amount),weight:FontWeight.w700)))])));})]);}
